# Writes src/modeldata.js: the light character models (art/models/*.glb) by file name; build.mjs copies them to dist/models/lo_<name>.glb (inline in index_single). Usage: python3 tools/makemodels.py
import base64, os
D = os.path.join(os.path.dirname(__file__), '..', 'art', 'models'); out = []
for f in sorted(os.listdir(D)):
    if f.endswith('.glb'): b = open(os.path.join(D, f), 'rb').read(); out.append("  %s: 'models/lo_%s.glb'" % (f[:-4], f[:-4])); print(f, round(len(b) / 1024), 'KB')
open(os.path.join(os.path.dirname(__file__), '..', 'src', 'modeldata.js'), 'w').write('// generated by tools/makemodels.py from art/models/*.glb\n// LAG FIX Nov 19 (owner 11:40): the light (packed) character models are files beside index.html (dist/models/lo_<name>.glb, copied by build.mjs), fetched when a\n// character is made, instead of 8.5 MB of base64 inside the page; index_single.html carries them inside as data: addresses (build.mjs), so it still plays from a folder\nexport const MODELS = {\n' + ',\n'.join(out) + '\n};\n')
